class Solution:
    def distanceTraveled(self, mainTank: int, additionalTank: int) -> int:
        used = 0
        distance = 0

        while mainTank > 0:
            mainTank -= 1
            distance += 10
            used += 1

            if used % 5 == 0:
                if additionalTank >= 1:
                    mainTank += 1
                    additionalTank -= 1

        return distance

class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        sum_digits = sum(int(d) for d in str(x)))
        if x % sum_digits == 0:
            return sum_digits
        else:
            return -1

from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Preprocess nums to collect positions of x
        positions = []
        for i, num in enumerate(nums):
            if num == x:
                positions.append(i)
        # Now process each query
        res = []
        for k in queries:
            if k <= len(positions):
                res.append(positions[k-1]]))
            else:
                res.append(-1)
        return res

